Un **vector** es un par de números (x, y). Los juegos lo usan para una **posición** (dónde), una **velocidad** (a qué ritmo y en qué dirección) y una **aceleración** (cómo cambia la velocidad). Todo motor y toda biblioteca matemática tiene uno (`glm::vec2`, el `Vector2` de raylib, el `FVector2D` de Unreal); este curso hace crecer el `Vec2` de la lección de C++ hasta convertirlo en una pequeña cabecera, y los fragmentos de aquí en adelante la incluyen:

```cpp
// vec2.h
#pragma once
#include <cmath>
#include <ostream>

struct Vec2 {
    float x = 0, y = 0;

    Vec2& operator+=(Vec2 o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(Vec2 o) { x -= o.x; y -= o.y; return *this; }

    float length() const { return std::sqrt(x * x + y * y); }
    Vec2 normalized() const {
        float len = length();
        return len > 0 ? Vec2{x / len, y / len} : *this;
    }
};

inline Vec2 operator+(Vec2 a, Vec2 b) { return {a.x + b.x, a.y + b.y}; }
inline Vec2 operator-(Vec2 a, Vec2 b) { return {a.x - b.x, a.y - b.y}; }
inline Vec2 operator*(Vec2 v, float k) { return {v.x * k, v.y * k}; }
inline Vec2 operator/(Vec2 v, float k) { return {v.x / k, v.y / k}; }
inline float dot(Vec2 a, Vec2 b) { return a.x * b.x + a.y * b.y; }

inline std::ostream& operator<<(std::ostream& os, Vec2 v) {
    return os << '(' << v.x << ", " << v.y << ')';
}
```

Son dos floats, así que se pasa **por valor** en todas partes, y `operator<<` lo imprime como `(x, y)`.

